CREATE TABLE review_inbox_events (event_id VARCHAR(120) PRIMARY KEY, event_type VARCHAR(120) NOT NULL, received_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE review_purchase_facts (user_id VARCHAR(120) NOT NULL, order_id VARCHAR(120) NOT NULL, product_id VARCHAR(120) NOT NULL, variant_id VARCHAR(120), seller_id VARCHAR(120), purchased_at TIMESTAMPTZ NOT NULL, PRIMARY KEY(user_id,order_id,product_id));
CREATE INDEX review_purchase_target_idx ON review_purchase_facts(user_id,product_id,seller_id);
CREATE TABLE reviews (id VARCHAR(120) PRIMARY KEY, user_id VARCHAR(120) NOT NULL, target_type VARCHAR(20) NOT NULL, target_id VARCHAR(120) NOT NULL, order_id VARCHAR(120) NOT NULL, rating INT NOT NULL CHECK(rating BETWEEN 1 AND 5), title VARCHAR(240), body TEXT NOT NULL, verified_purchase BOOLEAN NOT NULL, status VARCHAR(20) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(user_id,target_type,target_id,order_id));
CREATE INDEX review_page_idx ON reviews(target_type,target_id,status,created_at DESC,id DESC);
CREATE TABLE review_helpful_votes (review_id VARCHAR(120) NOT NULL REFERENCES reviews(id), user_id VARCHAR(120) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(review_id,user_id));
CREATE TABLE review_reports (id BIGSERIAL PRIMARY KEY, review_id VARCHAR(120) NOT NULL REFERENCES reviews(id), user_id VARCHAR(120) NOT NULL, reason VARCHAR(500) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(review_id,user_id));
CREATE TABLE review_moderation_audit (id BIGSERIAL PRIMARY KEY, review_id VARCHAR(120) NOT NULL, from_status VARCHAR(20), to_status VARCHAR(20) NOT NULL, actor_id VARCHAR(120) NOT NULL, reason VARCHAR(500), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE review_rating_aggregates (target_type VARCHAR(20) NOT NULL, target_id VARCHAR(120) NOT NULL, review_count BIGINT NOT NULL, rating_sum BIGINT NOT NULL, average NUMERIC(4,2) NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(target_type,target_id));
CREATE TABLE review_dlq (id BIGSERIAL PRIMARY KEY, event_id VARCHAR(120), error_text TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
